// src/tools/existingPlan.ts
async function checkExistingPlan(table, memberId, dates, replaceExisting) {
  const unique = [...new Set(dates)];
  const { data, error: error2 } = await supabase.from(table).select("assigned_date").eq("user_id", memberId).in("assigned_date", unique);
  if (error2) return { blocked: `Error comprobando el plan actual: ${error2.message}`, note: "", existingDates: [] };
  const existingDates = [...new Set((data ?? []).map((r) => r.assigned_date))].sort();
  if (existingDates.length === 0) return { blocked: null, note: "", existingDates };
  const what = table === "workout_assignments" ? "ejercicios" : "comidas";
  if (!replaceExisting) {
    return {
      blocked: JSON.stringify({
        error: true,
        motivo: `El socio ya tiene ${data.length} ${what} asignados en ${existingDates.length} de esas fechas (${existingDates.slice(0, 6).join(", ")}${existingDates.length > 6 ? "\u2026" : ""}). No se ha guardado nada. Si el usuario ha pedido rehacer o sustituir el plan, vuelve a llamar con replace_existing=true. Si no (p.ej. una tarea autom\xE1tica que ya se hizo), no asignes nada y expl\xEDcalo.`
      }),
      note: "",
      existingDates
    };
  }
  return {
    blocked: null,
    note: ` Sustituye ${data.length} ${what} que ya ten\xEDa en ${existingDates.length} de esas fechas.`,
    existingDates
  };
}
async function findMissingIds(table, ids) {
  const unique = [...new Set(ids)];
  const { data, error: error2 } = await supabase.from(table).select("id").in("id", unique);
  if (error2) throw new Error(`Error comprobando ${table}: ${error2.message}`);
  const found = new Set((data ?? []).map((r) => r.id));
  return unique.filter((id) => !found.has(id));
}
async function saveReplacing(table, memberId, existingDates, inserts) {
  let previous = [];
  if (existingDates.length > 0) {
    const { data, error: error3 } = await supabase.from(table).select("*").eq("user_id", memberId).in("assigned_date", existingDates);
    if (error3) return `Error leyendo el plan anterior: ${error3.message}`;
    previous = data ?? [];
    const { error: delError } = await supabase.from(table).delete().eq("user_id", memberId).in("assigned_date", existingDates);
    if (delError) return `Error sustituyendo el plan anterior: ${delError.message}`;
  }
  const { error: error2 } = await supabase.from(table).insert(inserts);
  if (!error2) return null;
  if (previous.length > 0) {
    const { error: restoreError } = await supabase.from(table).insert(previous);
    if (restoreError) {
      return `Error guardando el plan nuevo (${error2.message}) y NO se pudo restaurar el anterior (${restoreError.message}). Avisa al usuario.`;
    }
    return `Error guardando el plan nuevo: ${error2.message}. No se ha cambiado nada (se ha restaurado el plan anterior).`;
  }
  return `Error guardando el plan: ${error2.message}`;
}
async function deletePlanRange(table, memberId, from, to, apply) {
  if (!apply) {
    const { count: count2, error: error3 } = await supabase.from(table).select("*", { count: "exact", head: true }).eq("user_id", memberId).gte("assigned_date", from).lte("assigned_date", to);
    return { count: count2 ?? 0, error: error3?.message ?? null };
  }
  const { count, error: error2 } = await supabase.from(table).delete({ count: "exact" }).eq("user_id", memberId).gte("assigned_date", from).lte("assigned_date", to);
  return { count: count ?? 0, error: error2?.message ?? null };
}

// src/tools/personalRecordsCheck.ts
var TOLERANCE = 0.1;
async function checkAgainstPersonalRecords(memberId, planned, justification, userSetExerciseIds = []) {
  const userSet = new Set(userSetExerciseIds);
  const userNote = userSet.size > 0 ? ` ${userSet.size} ejercicio(s) con el peso indicado por el usuario.` : "";
  const exerciseIds = [...new Set(planned.map((p) => p.exercise_id))].filter((id) => !userSet.has(id));
  if (exerciseIds.length === 0) return { blocked: null, note: userNote };
  const { data: records, error: error2 } = await supabase.from("personal_records").select("exercise_id, max_weight_kg").eq("user_id", memberId).in("exercise_id", exerciseIds);
  if (error2) return { blocked: `Error consultando las marcas personales del socio: ${error2.message}`, note: "" };
  const withRecord = (records ?? []).filter((r) => Number(r.max_weight_kg) > 0);
  if (withRecord.length === 0) {
    return { blocked: null, note: ` El socio no tiene marcas registradas en estos ejercicios.${userNote}` };
  }
  const { data: exercises } = await supabase.from("exercises").select("id, name, category").in("id", withRecord.map((r) => r.exercise_id));
  const info = new Map((exercises ?? []).map((e) => [e.id, e]));
  const deviations = [];
  for (const record of withRecord) {
    const pr = Number(record.max_weight_kg);
    const exercise = info.get(record.exercise_id);
    const weights = planned.filter((p) => p.exercise_id === record.exercise_id).map((p) => Number(p.target_weight ?? 0));
    const relevant = exercise?.category?.toLowerCase().includes("cardio") ? weights.filter((w) => w > 0) : weights;
    const off = relevant.filter((w) => w < pr * (1 - TOLERANCE) || w > pr * (1 + TOLERANCE));
    if (off.length > 0) {
      deviations.push(
        `${exercise?.name?.trim() ?? record.exercise_id}: marca ${pr} kg, en el plan ${[...new Set(relevant)].join("/")} kg`
      );
    }
  }
  if (deviations.length === 0) {
    return { blocked: null, note: ` Pesos coherentes con sus ${withRecord.length} marcas personales.${userNote}` };
  }
  if (justification?.trim()) {
    return { blocked: null, note: ` Pesos distintos de su marca (${deviations.join("; ")}): ${justification.trim()}${userNote}` };
  }
  return {
    blocked: JSON.stringify({
      error: true,
      motivo: `No se ha guardado nada: algunos pesos se alejan m\xE1s de un 10 % de las marcas personales del socio en esos ejercicios: ${deviations.join("; ")}. Ajusta esos pesos a partir de su marca (no por debajo salvo motivo, y progresando poco a poco) y vuelve a llamar. Si hay un motivo real para apartarse (semana de descarga, lesi\xF3n, la marca est\xE1 registrada de otra forma, p.ej. la suma de las dos mancuernas...), vuelve a llamar explic\xE1ndolo en personal_records_justification. Si esos pesos los ha dictado el usuario, incluye esos ejercicios en user_set_weight_exercise_ids.`
    }),
    note: ""
  };
}

