var MEAL_TYPES = [
  "Desayuno",
  "Media ma\xF1ana",
  "Almuerzo",
  "Comida",
  "Merienda",
  "Cena",
  "Snack",
  "Pre-Entreno",
  "Intra-Entreno",
  "Post-Entreno"
];
var listRecipes = zodFunction({
  name: "list_recipes",
  description: "Busca platos/recetas en el cat\xE1logo de nutrici\xF3n del gimnasio (tabla recipes), filtrando por tipo de comida y/o nombre. \xDAsala siempre para obtener los recipe_id reales antes de asignar un plan de comidas con assign_meal_plan: nunca inventes recipe_id ni nombres de platos que no existan en el cat\xE1logo. Los campos calories/protein/carbs/fat casi siempre est\xE1n a 0 porque no se han rellenado en el sistema: si es as\xED, ESTIMA t\xFA los macros por el nombre del plato para decidir cu\xE1les encajan con el objetivo del cliente, no los ignores por estar a 0.",
  parameters: external_exports.object({
    category: external_exports.enum(MEAL_TYPES).nullable().optional().describe("Filtra por tipo de comida."),
    search: external_exports.string().nullable().optional().describe("Texto a buscar en el nombre del plato."),
    limit: external_exports.number().int().min(1).max(100).nullable().optional().describe("M\xE1ximo de resultados (por defecto 50).")
  }),
  function: async (input) => {
    let query = supabase.from("recipes").select("id, name, category, calories, protein, carbs, fat, description").order("name").limit(Math.max(input.limit ?? 50, 15));
    if (input.category) query = query.eq("category", input.category);
    if (input.search) query = query.ilike("name", `%${input.search}%`);
    const { data, error: error2 } = await query;
    if (error2) return `Error consultando recetas: ${error2.message}`;
    if (!data || data.length === 0) return "No se encontraron platos con esos filtros en el cat\xE1logo.";
    const allMacrosMissing = data.every((r) => !r.calories && !r.protein && !r.carbs && !r.fat);
    if (allMacrosMissing) {
      return JSON.stringify(
        {
          aviso: "Estos platos no tienen calories/protein/carbs/fat rellenados en el sistema (est\xE1n a 0). ESTIMA t\xFA los macros aproximados de cada uno por su nombre para poder elegir los m\xE1s adecuados al objetivo del cliente (p.ej. para bajar de peso, prioriza los de menor calor\xEDa estimada y mayor prote\xEDna). Indica en tu resumen que son estimaciones tuyas, no datos verificados del cat\xE1logo.",
          resultados: data
        },
        null,
        2
      );
    }
    return JSON.stringify(data, null, 2);
  }
});
