// src/cloud/cloudTools.ts
var tools = [
  listMembers,
  getMember,
  updateMember,
  listClasses,
  listDisciplines,
  createClass,
  listInvoices,
  registerPayment,
  dashboardSummary,
  listExercises,
  listWorkoutPlan,
  assignWorkoutPlan,
  deleteWorkoutPlan,
  listPersonalRecords,
  listRecipes,
  listMealPlan,
  assignMealPlan,
  deleteMealPlan,
  listClassBookings,
  listWorkoutLogs,
  listNutritionLogs,
  listCalorieGoalHistory
];
var byName = new Map(tools.map((t) => [t.function.name, t]));
var responseTools = tools.map((t) => ({
  type: "function",
  name: t.function.name,
  description: t.function.description ?? null,
  parameters: t.function.parameters ?? {},
  strict: t.function.strict ?? true
}));
async function runCloudTool(name, args) {
  const tool = byName.get(name);
  if (!tool?.$callback) return `La herramienta "${name}" no est\xE1 disponible en las tareas autom\xE1ticas.`;
  try {
    const output = await tool.$callback(tool.$parseRaw(args));
    return typeof output === "string" ? output : JSON.stringify(output);
  } catch (err) {
    return `Error ejecutando ${name}: ${err instanceof Error ? err.message : String(err)}`;
  }
}

